using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEditor;using TMPro;using Mewgic.Core;
namespace Mewgic {
public sealed class BottleLayoutProbe:MonoBehaviour {
 readonly List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();bool had;string save;const string Output="docs/Part10E/";
 static BottleLayoutProbe active;
 void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);save=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();Application.logMessageReceived+=Log;}
 void Log(string m,string stack,LogType t){if(t==LogType.Warning)warnings.Add(m);if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
 void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
 Puzzle Model=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(FindFirstObjectByType<PrototypeApp>());
 void Tap(string name){var g=GameObject.Find(name);Check(g!=null,"Buton mevcut: "+name);g.GetComponent<Button>().onClick.Invoke();}
 void Empty(){Check(!FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Any(t=>t.text.StartsWith("Önce kaynak")),"Sabit öğretici hiçbir görünür TMP metninde yok");Check(GameObject.Find("Status").GetComponent<TMP_Text>().text=="","Başlangıç/Restart açıklaması boş");var r=GameObject.Find("TutorialOverlay");Check(r!=null&&r.GetComponentsInChildren<TMP_Text>(true).Length==0&&r.GetComponentsInChildren<Graphic>(true).Length==0,"TutorialOverlay boş ve dokunma yakalamıyor");}
 IEnumerator Start(){var run=Run();string error=null;while(true){bool more=false;object next=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){error=e.ToString();}if(!more||error!=null)break;yield return next;}Application.logMessageReceived-=Log;bool intact=had==PlayerPrefs.HasKey(GameplayProgress.StorageKey)&&save==PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();File.WriteAllText(Output+"UI_AUDIT.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null&&errors.Count==0&&intact,error,errors,warnings,checks,playerSaveIntact=intact},Newtonsoft.Json.Formatting.Indented));EditorApplication.isPlaying=false;}
 void Counters(int id,int moves){Check(GameObject.Find("LevelValue").GetComponent<TMP_Text>().text=="Bölüm "+id,"Gerçek bölüm: "+id);Check(GameObject.Find("Moves").GetComponent<TMP_Text>().text=="Hamle "+moves,"Gerçek hamle: "+moves);}
 IEnumerator Run(){yield return null;yield return null;var guide=FindFirstObjectByType<Mewgic.UI.PawGuide>();guide.Continue();yield return new WaitForSecondsRealtime(.3f);Capture(Output+"Tutorial.png",900,1600);guide.Close();ModelLayouts();foreach(int h in new[]{1600,1950,2000})Capture(Output+"After-"+h+".png",900,h,h==2000);ScreenCapture.CaptureScreenshot(Output+"After-GameView.png");yield return new WaitForEndOfFrame();yield return null;
 Tap("Bottle 1");yield return new WaitForSecondsRealtime(.15f);Check(GameObject.Find("Bottle 1").GetComponent<GameplayBottleView>().Rig.anchoredPosition.y>5,"Seçilen şişe yükseliyor");Tap("Bottle 2");Check(Model.Moves==0,"Geçersiz hamle veri değiştirmedi");var move=PuzzleSolver.Solve(Model.Export()).Moves[0];Tap("Bottle "+(move.Target+1));var destination=GameObject.Find("Bottle "+(move.Target+1)).GetComponent<RectTransform>();var position=destination.position;var size=destination.rect.size;var gp=FindFirstObjectByType<GameplayPresentation>();yield return new WaitForSecondsRealtime(.1f);Tap("Pause");var pausedRig=GameObject.Find("Bottle "+(move.Source+1)).GetComponent<GameplayBottleView>().Rig;var pausedPosition=pausedRig.position;var pausedAngle=pausedRig.localRotation;yield return new WaitForSecondsRealtime(.15f);Check(pausedRig.position==pausedPosition&&pausedRig.localRotation==pausedAngle,"Pause aktarım pozunu dondurdu");Tap("Resume");float end=Time.realtimeSinceStartup+.8f;bool tilted=false;while(Time.realtimeSinceStartup<end){Check(destination.position==position&&destination.rect.size==size,"Aktarımda hedef sabit");var rig=GameObject.Find("Bottle "+(move.Source+1)).GetComponent<GameplayBottleView>().Rig;tilted|=Mathf.Abs(Mathf.DeltaAngle(rig.localEulerAngles.z,0))>20;yield return null;}yield return new WaitForSecondsRealtime(.4f);Check(tilted&&Model.Moves==1,"Eğilme/aktarım/dönüş tamamlandı");Tap("Undo");Check(Model.Moves==0,"Undo korundu");Tap("Restart");Check(Model.Moves==0,"Restart korundu");Tap("Pause");Check(FindFirstObjectByType<GameplayHud>().IsPaused,"Pause korundu");Tap("Resume");
 var board=GameObject.Find("Bottle board").GetComponent<RectTransform>();var originals=board.GetComponentsInChildren<GameplayBottleView>().Select(v=>(RectTransform)v.transform).ToArray();foreach(var original in originals)original.gameObject.SetActive(false);
 foreach(int count in new[]{2,6,12}){var fixture=new List<RectTransform>();for(int i=0;i<count;i++){var go=new GameObject("FixtureBottle"+i,typeof(RectTransform),typeof(Image),typeof(Button));var r=(RectTransform)go.transform;r.SetParent(board,false);go.GetComponent<Image>().color=Color.clear;go.AddComponent<GameplayBottleView>().Initialize(Resources.Load<Sprite>("Gameplay/Gameplay_GlassShell_v001"),new[]{Color.cyan,Color.magenta});go.GetComponent<GameplayBottleView>().Present(new[]{i%2,i%2,1-i%2,1-i%2},false);fixture.Add(r);}gp.Bind(fixture.ToArray());foreach(int h in new[]{1600,1950,2000})Capture(Output+"Fixture-"+count+"-"+h+".png",900,h,h==2000);foreach(var r in fixture)DestroyImmediate(r.gameObject);}
 foreach(var original in originals)original.gameObject.SetActive(true);gp.Bind(originals);Check(GameplayProgress.Current.Snapshot.levels.Count==0,"Yerleşim fixture'ları bölüm verisine yazmadı");foreach(var move2 in PuzzleSolver.Solve(Model.Export()).Moves){Tap("Bottle "+(move2.Source+1));Tap("Bottle "+(move2.Target+1));yield return new WaitForSecondsRealtime(1.1f);}Tap("NextLevel");yield return null;yield return null;FindFirstObjectByType<Mewgic.UI.PawGuide>()?.Close();Check(Model.Count==5,"Gerçek ikinci bölüm5 şişe");foreach(int h in new[]{1600,1950,2000})Capture(Output+"FiveBottles-"+h+".png",900,h,h==2000);
 }
 void ModelLayouts(){foreach(var size in new[]{new Vector2(630,960),new Vector2(570,1060),new Vector2(525,980)})foreach(int count in new[]{2,3,4,5,6,8,12,20,32}){var slots=new List<Rect>();for(int i=0;i<count;i++){var r=GameplayPresentation.Slot(i,count,size);var px=new Rect(r.x*size.x,r.y*size.y,r.width*size.x,r.height*size.y);Check(px.width>=44&&px.height>=100,"Minimum44 alanı: "+count);Check(px.xMin>=0&&px.xMax<=size.x+.1f&&px.yMin>=0&&px.yMax<=size.y+.1f,"Taşma yok: "+count);foreach(var other in slots)Check(!other.Overlaps(px),"Cam/dokunma alanları ayrık: "+count);slots.Add(px);}}
 }
 Rect Bounds(RectTransform r,RectTransform relative){var c=new Vector3[4];r.GetWorldCorners(c);var a=(Vector2)relative.InverseTransformPoint(c[0]);var b=(Vector2)relative.InverseTransformPoint(c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
 void ValidateLayout(RectTransform safe,int height){if(safe==null)return;var gp=FindFirstObjectByType<GameplayPresentation>();if(gp==null)return;var views=FindObjectsByType<GameplayBottleView>(FindObjectsSortMode.None);var rectangles=new List<Rect>();foreach(var view in views){var r=Bounds((RectTransform)view.transform,safe);Check(r.width*safe.GetComponentInParent<Canvas>().scaleFactor>=44,"Dokunma en az44px: "+height);foreach(var other in rectangles)Check(!r.Overlaps(other),"Şişeler çakışmıyor: "+height);rectangles.Add(r);foreach(string name in new[]{"GameplayWizardCat","GameplayBoosters","GameplayHUD"}){var obj=GameObject.Find(name);if(obj!=null)Check(!r.Overlaps(Bounds((RectTransform)obj.transform,safe)),"UI/kedi ile çakışma yok: "+name+height);}var point=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(Camera.main,view.transform.TransformPoint(((RectTransform)view.transform).rect.center))};var hits=new List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(point,hits);Check(hits.Count>0&&hits[0].gameObject==view.gameObject,"Doğru şişe gerçek raycast hedefi: "+view.name+" ilk="+(hits.Count>0?hits[0].gameObject.name:"none"));}}
        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                foreach(var text in FindObjectsByType<TMPro.TMP_Text>(FindObjectsSortMode.None))text.ForceMeshUpdate();FindFirstObjectByType<GameplayHud>()?.Layout();Canvas.ForceUpdateCanvases();camera.Render();ValidateLayout(safe,height);RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
}
}
